@Test
public void testResolveAddress() throws IOException {
    // test it with all interfaces
    Enumeration<NetworkInterface> en = NetworkInterface.getNetworkInterfaces();
    while (en.hasMoreElements()) {
        NetworkInterface netint = (NetworkInterface) en.nextElement();
        Enumeration<InetAddress> inetAddresses = netint.getInetAddresses();
        for (InetAddress inetAddress : Collections.list(inetAddresses)) {
            if (inetAddress instanceof Inet4Address) {
                long start = System.currentTimeMillis();
                String reverse = DnsUtil.resolveAddress(inetAddress.getHostAddress());
                long end = System.currentTimeMillis();
                // we know that java.net.InetAddress's getHostName takes > 4.5s if
                // there is no reverse address assigned to it
                // DnsUtil should resolve any address in less than 5 seconds or fail
                assertTrue("DnsUtil.resolveAddress takes " + (end - start) + " millis, it should be shorter than five seconds", end - start < 5000);
                if (inetAddress.toString().substring(1).equals(reverse)) {
                    out.printf("InetAddress %s on interface %s does not have reverse dns name, so their reverse remains: %s\n", inetAddress, netint.getDisplayName(), reverse);
                } else {
                    if (inetAddress.isLoopbackAddress()) {
                        out.printf("InetAddress %s on loopback interface %s obtained reverse name as %s\n", inetAddress, netint.getDisplayName(), reverse);
                    } else {
                        out.printf("InetAddress %s on interface %s has reverse dns name: %s\n", inetAddress, netint.getDisplayName(), reverse);
                        try {
                            InetAddress checkedAddr = Address.getByName(reverse);
                            assertEquals(inetAddress, checkedAddr);
                        } catch (UnknownHostException uhex) {
                            fail("InetAddress " + inetAddress + " on interface " + netint.getDisplayName() + " got " + reverse + " reverse dns name which in return is an unknown host!");
                        }
                    }
                }
            }
        }
    }
}

