            problems.append(line).append("\n");
            failed = true;
        }
        assertFalse(problems.toString(), failed);
        reader.close();
        fs.delete(new Path("input"), true);
        fs.delete(new Path("output"), true);
        fs.delete(new Path("report"), true);
        LOG.info("Completed TeraSort run {} of {}", i + 1, runs);
    }
}

